; TakeCommand [C] marks the queue entry free, SoundCommand = the command, then DispatchCommand
TakeCommand:
	ld a,0ffh	; 0169
	ld (0fe2ch),a	; 016B
	ld (hl),000h	; 016E
	inc hl	; 0170
	ld a,(hl)	; 0171
